import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`newsletter`,heroTitle:`Launch a newsletter on autopilot`,heroSubtitle:`Perplexity Computer researches your industry, writes your newsletter, and sends it through your email platform — every week, automatically.`,inputUrlCta:`Start my newsletter`,inputUrlPrefill:`Go to {url} and set up a weekly newsletter for this business. Research the industry, audience, and trending topics each week. Write a polished newsletter issue with a compelling subject line, intro, 3–5 curated stories or insights with commentary, and a closing CTA. Match the brand voice and tone from the website. Format it with proper HTML email structure, inline styles, mobile responsiveness, and preview text. Connect to my email platform, create the campaign, and schedule it for delivery. Set this up as a recurring weekly workflow that researches fresh content, writes a new issue, and sends it every week without manual input.`,heroOverlaySteps:[`Researching trending topics and news in your industry`,`Writing a polished issue with curated insights and commentary`,`Formatting for your email platform and scheduling delivery`,`Recurring weekly workflow, hands-free after setup`],generatingSteps:[`Visiting {url} to understand your brand voice, audience, and industry`,`Designing an agent to research trending topics and curate content weekly`,`Configuring newsletter writing, formatting, and email platform integration`,`Setting up recurring weekly delivery with fresh content every issue`],featureSectionTitle:`From zero to weekly newsletter`,featureCardTitles:[`Connects to your email tools`,`Issues ready to send`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Notion, Google Sheets, and more — Computer sends your newsletter through your existing email platform with no manual setup.`,`Subject lines. Curated stories. Brand-matched copy. Computer writes and formats each issue — ready for your review or auto-send.`],capabilitySectionTitle:`Your editorial team, every week`,capabilitySectionSubtitle:`Enter your URL, get back a newsletter that runs itself.`,capabilityCards:[{title:`Weekly Research`,description:`Computer scans your industry every week for trending topics, news, and insights worth sharing with your audience.`},{title:`Newsletter Writing`,description:`Computer writes each issue with a compelling subject line, curated stories, commentary, and a closing CTA — in your brand voice.`},{title:`Email Platform Integration`,description:`Computer connects to your email platform, creates the campaign, formats the email, and schedules delivery — no manual steps.`},{title:`Automated Delivery`,description:`Computer sends your newsletter every week on schedule — or queues it for your review before sending.`},{title:`Learns Your Voice`,description:`Computer remembers your brand tone, past issues, and audience preferences — so every issue sounds like you wrote it.`},{title:`Performance Tracking`,description:`Computer tracks opens, clicks, and engagement — and adjusts topics and subject lines based on what resonates.`}]});export{t as default};
